package com.climbme.app.dashboard;
import com.climbme.app.auth.UserAccount;import com.climbme.app.climbing.*;import java.time.*;import java.util.*;import java.util.function.*;import java.util.stream.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class DashboardService{private final ClimbingAttemptRepository attempts;private final AchievementService achievements;public DashboardService(ClimbingAttemptRepository attempts,AchievementService achievements){this.attempts=attempts;this.achievements=achievements;}@Transactional(readOnly=true) public DashboardResponse dashboard(UserAccount user){List<ClimbingAttempt>a=attempts.findByUserIdOrderByClimbedOnDescIdDesc(user.getId());List<ClimbingAttempt>s=a.stream().filter(ClimbingAttempt::isSent).toList();Function<ClimbingAttempt,String> grade=x->x.getGrade().label();Comparator<ClimbingAttempt> hard=Comparator.comparingInt(x->x.getGrade().rank());String hardest=s.stream().max(hard).map(grade).orElse(null);long active=a.stream().collect(Collectors.groupingBy(x->x.getLocation()+"|"+x.getSector()+"|"+x.getRouteName())).values().stream().filter(g->g.stream().noneMatch(ClimbingAttempt::isSent)).count();DashboardResponse.Kpis k=new DashboardResponse.Kpis(a.size(),s.size(),a.isEmpty()?0:100d*s.size()/a.size(),hardest,hardest(s,ClimbingAttempt.Style.ONSIGHT),hardest(s,ClimbingAttempt.Style.FLASH),hardest(s,ClimbingAttempt.Style.REDPOINT),active,a.stream().map(ClimbingAttempt::getClimbedOn).distinct().count(),a.stream().map(ClimbingAttempt::getLocation).distinct().count());return new DashboardResponse(k,points(s,x->YearMonth.from(x.getClimbedOn()).toString(),list->list.stream().mapToInt(x->x.getGrade().rank()).max().orElse(0)),points(s,grade,List::size),points(a,x->x.getStyle().name(),List::size),attemptsToSend(a),locationRates(a),points(a,x->YearMonth.from(x.getClimbedOn()).toString(),List::size),achievements.derive(a));}private String hardest(List<ClimbingAttempt>a,ClimbingAttempt.Style st){return a.stream().filter(x->x.getStyle()==st).max(Comparator.comparingInt(x->x.getGrade().rank())).map(x->x.getGrade().label()).orElse(null);}private List<DashboardResponse.Point> points(List<ClimbingAttempt>a,Function<ClimbingAttempt,String> key,Function<List<ClimbingAttempt>,Number> value){return a.stream().collect(Collectors.groupingBy(key,TreeMap::new,Collectors.toList())).entrySet().stream().map(e->new DashboardResponse.Point(e.getKey(),value.apply(e.getValue()).doubleValue())).toList();}private List<DashboardResponse.Point> attemptsToSend(List<ClimbingAttempt>a){return a.stream().filter(ClimbingAttempt::isSent).collect(Collectors.groupingBy(x->x.getGrade().label(),TreeMap::new,Collectors.averagingInt(ClimbingAttempt::getAttemptNumber))).entrySet().stream().map(e->new DashboardResponse.Point(e.getKey(),e.getValue())).toList();}private List<DashboardResponse.Point> locationRates(List<ClimbingAttempt>a){return a.stream().collect(Collectors.groupingBy(ClimbingAttempt::getLocation,TreeMap::new,Collectors.toList())).entrySet().stream().map(e->new DashboardResponse.Point(e.getKey(),100d*e.getValue().stream().filter(ClimbingAttempt::isSent).count()/e.getValue().size())).toList();}}
